const rows = $('Pack CRM Rows').first().json.crmRows || [];
const incoming = $input.all().map(item => item.json || {});
const clean = value => String(value ?? '').replace(/\s+/g, ' ').trim();
const time = value => {
  const parsed = new Date(value || 0).getTime();
  return Number.isFinite(parsed) ? parsed : 0;
};
const latestByThread = new Map();
for (const message of incoming) {
  const threadId = clean(message.threadId || message.thread_id);
  if (!threadId) continue;
  const current = latestByThread.get(threadId);
  const messageTime = time(message.date || message.internalDate);
  if (!current || messageTime >= current._messageTime) {
    latestByThread.set(threadId, { ...message, _messageTime: messageTime });
  }
}
const output = [];
for (const [threadId, message] of latestByThread.entries()) {
  const candidates = rows
    .filter(row => clean(row.Gmail_Thread_ID) === threadId && !clean(row.Reply_At))
    .sort((a, b) => time(b.Sent_At) - time(a.Sent_At));
  const row = candidates[0];
  if (!row) continue;
  const sentAt = time(row.Sent_At);
  if (sentAt && message._messageTime && message._messageTime <= sentAt) continue;
  const snippet = clean(
    message.snippet ||
    message.textPlain ||
    message.text ||
    message.Subject ||
    message.subject
  ).slice(0, 500);
  const subject = clean(message.Subject || message.subject);
  const probe = clean(`${subject} ${snippet}`).toLowerCase();
  const positive = /chętnie|zainteres|poprosimy|zagramy|dodamy|recenzj|wywiad|propozycj|pasuje|jasne|super|interested|sounds good|happy to|would love|please send|let'?s do|available|confirmed/.test(probe);
  const negative = /nie jesteśmy|nie możemy|nie tym razem|odmaw|nie pasuje|rezygn|not interested|not a fit|cannot|can'?t|decline|pass this time|no availability/.test(probe);
  const replyClass = positive ? 'Pozytywna' : negative ? 'Negatywna' : 'Neutralna';
  const nextStep = positive
    ? 'Odpowiedz osobiście w 24 h i ustal konkret'
    : negative
      ? 'Podziękuj; zamknij bez kolejnego follow-upu'
      : 'Przeczytaj pełny wątek i zdecyduj w 24 h';
  const replyAt = message._messageTime
    ? new Date(message._messageTime).toISOString()
    : new Date().toISOString();
  output.push({
    json: {
      Record_ID: row.Record_ID,
      Status: 'Odpowiedź',
      Reply_At: replyAt,
      Reply_Summary: snippet || 'Odpowiedź w Gmailu — otwórz wątek',
      Reply_Class: replyClass,
      Next_Step: nextStep,
      Discord_Status: 'Pending',
      Last_Synced_At: new Date().toISOString()
    }
  });
}
return output;

const replies = $input.all().map(item => item.json || {});
if (!replies.length) return [];
const lines = replies.slice(0, 8).map(row =>
  `• **${row.Record_ID || 'kontakt'}** — ${row.Reply_Class || 'Odpowiedź'}: ${String(row.Reply_Summary || '').slice(0, 180)}\n  Następny krok: ${row.Next_Step || 'sprawdź w Gmailu'}`
);
const more = replies.length > 8 ? `\n\nPozostałe odpowiedzi: ${replies.length - 8} — sprawdź OUTREACH_LOG.` : '';
const message = (`📬 **VIRYA — nowe odpowiedzi (${replies.length})**\n${lines.join('\n')}${more}`).slice(0, 1950);
return [{ json: { discord_message: message, allowed_mentions: { parse: [] } } }];

